"""sklearn.metrics.cluster — clustering-quality metrics."""

import numpy as _np


def adjusted_rand_score(labels_true, labels_pred):
    """ARI — chance-adjusted Rand index. Range [-1, 1]."""
    labels_true = _np.asarray(labels_true); labels_pred = _np.asarray(labels_pred)
    n = len(labels_true)
    if n == 0: return 0.0
    cont = _contingency(labels_true, labels_pred)
    sum_comb_c = sum(n_c * (n_c - 1) / 2 for n_c in cont.sum(axis=1))
    sum_comb_k = sum(n_k * (n_k - 1) / 2 for n_k in cont.sum(axis=0))
    sum_comb = sum(n_ij * (n_ij - 1) / 2 for n_ij in cont.flatten())
    expected = sum_comb_c * sum_comb_k / (n * (n - 1) / 2)
    max_index = (sum_comb_c + sum_comb_k) / 2
    if max_index == expected: return 0.0
    return (sum_comb - expected) / (max_index - expected)


def adjusted_mutual_info_score(labels_true, labels_pred, *, average_method='arithmetic'):
    """AMI — chance-adjusted mutual info."""
    mi = mutual_info_score(labels_true, labels_pred)
    h_t = entropy(labels_true); h_p = entropy(labels_pred)
    emi = mi  # Simplified — proper EMI needs hypergeometric expectation.
    avg = {'arithmetic': (h_t + h_p) / 2,
            'max': max(h_t, h_p), 'min': min(h_t, h_p),
            'geometric': (h_t * h_p) ** 0.5}.get(average_method, (h_t + h_p) / 2)
    return (mi - emi) / (avg - emi) if avg != emi else 0.0


def mutual_info_score(labels_true, labels_pred, *, contingency=None):
    """Mutual information between two clusterings."""
    if contingency is None:
        contingency = _contingency(labels_true, labels_pred)
    contingency = _np.asarray(contingency, dtype=float)
    contingency_sum = contingency.sum()
    pi = contingency.sum(axis=1)
    pj = contingency.sum(axis=0)
    nz = contingency.nonzero()
    nz_val = contingency[nz]
    log_outer = _np.log(pi[nz[0]]) + _np.log(pj[nz[1]]) - _np.log(contingency_sum)
    mi = (nz_val / contingency_sum *
          (_np.log(nz_val) - _np.log(contingency_sum) - log_outer + _np.log(contingency_sum)))
    return mi.sum()


def normalized_mutual_info_score(labels_true, labels_pred, *, average_method='arithmetic'):
    mi = mutual_info_score(labels_true, labels_pred)
    h_t = entropy(labels_true); h_p = entropy(labels_pred)
    avg = {'arithmetic': (h_t + h_p) / 2,
            'max': max(h_t, h_p), 'min': min(h_t, h_p),
            'geometric': (h_t * h_p) ** 0.5}.get(average_method, (h_t + h_p) / 2)
    return mi / avg if avg else 0.0


def fowlkes_mallows_score(labels_true, labels_pred, *, sparse=False):
    cont = _contingency(labels_true, labels_pred)
    tk = sum(n_ij * (n_ij - 1) / 2 for n_ij in cont.flatten())
    pk = sum(n_c * (n_c - 1) / 2 for n_c in cont.sum(axis=1))
    qk = sum(n_k * (n_k - 1) / 2 for n_k in cont.sum(axis=0))
    return tk / (pk * qk) ** 0.5 if pk and qk else 0.0


def homogeneity_score(labels_true, labels_pred):
    h_t = entropy(labels_true)
    if h_t == 0: return 1.0
    return 1.0 - _conditional_entropy(labels_true, labels_pred) / h_t


def completeness_score(labels_true, labels_pred):
    return homogeneity_score(labels_pred, labels_true)


def v_measure_score(labels_true, labels_pred, *, beta=1.0):
    h = homogeneity_score(labels_true, labels_pred)
    c = completeness_score(labels_true, labels_pred)
    if h + c == 0: return 0.0
    return (1 + beta) * h * c / (beta * h + c)


def homogeneity_completeness_v_measure(labels_true, labels_pred, *, beta=1.0):
    return (homogeneity_score(labels_true, labels_pred),
            completeness_score(labels_true, labels_pred),
            v_measure_score(labels_true, labels_pred, beta=beta))


def silhouette_score(X, labels, *, metric='euclidean', sample_size=None,
                       random_state=None, **kwds):
    """Mean silhouette coefficient."""
    return silhouette_samples(X, labels, metric=metric, **kwds).mean()


def silhouette_samples(X, labels, *, metric='euclidean', **kwds):
    """Per-sample silhouette score in [-1, 1]."""
    from sklearn.metrics.pairwise import pairwise_distances
    X = _np.asarray(X); labels = _np.asarray(labels)
    D = pairwise_distances(X, metric=metric, **kwds)
    unique = _np.unique(labels)
    if len(unique) < 2:
        return _np.zeros(len(X))
    scores = _np.zeros(len(X))
    for i in range(len(X)):
        own = labels[i]
        in_cluster = labels == own
        in_cluster[i] = False  # exclude self
        if in_cluster.sum() > 0:
            a = D[i, in_cluster].mean()
        else:
            a = 0
        b = _np.inf
        for c in unique:
            if c == own: continue
            mask = labels == c
            if mask.sum():
                b = min(b, D[i, mask].mean())
        scores[i] = (b - a) / max(a, b) if max(a, b) > 0 else 0
    return scores


def calinski_harabasz_score(X, labels):
    """Variance-ratio score — higher = better-defined clusters."""
    X = _np.asarray(X); labels = _np.asarray(labels)
    n_samples, _ = X.shape
    unique = _np.unique(labels)
    k = len(unique)
    if k == 1: return 1.0
    overall_mean = X.mean(axis=0)
    bgss = 0; wgss = 0
    for c in unique:
        mask = labels == c
        cluster_mean = X[mask].mean(axis=0)
        bgss += mask.sum() * _np.sum((cluster_mean - overall_mean) ** 2)
        wgss += _np.sum((X[mask] - cluster_mean) ** 2)
    return (bgss / (k - 1)) / (wgss / (n_samples - k)) if wgss > 0 else 0.0


def davies_bouldin_score(X, labels):
    """Davies-Bouldin index — lower = better separation."""
    X = _np.asarray(X); labels = _np.asarray(labels)
    unique = _np.unique(labels)
    k = len(unique)
    if k == 1: return 0.0
    centroids = _np.array([X[labels == c].mean(axis=0) for c in unique])
    s = _np.array([_np.linalg.norm(X[labels == c] - centroids[i], axis=1).mean()
                    for i, c in enumerate(unique)])
    db_scores = []
    for i in range(k):
        max_r = 0
        for j in range(k):
            if i == j: continue
            d = _np.linalg.norm(centroids[i] - centroids[j])
            if d > 0:
                max_r = max(max_r, (s[i] + s[j]) / d)
        db_scores.append(max_r)
    return _np.mean(db_scores)


def rand_score(labels_true, labels_pred):
    """Raw (unadjusted) Rand index."""
    labels_true = _np.asarray(labels_true); labels_pred = _np.asarray(labels_pred)
    n = len(labels_true)
    if n < 2: return 1.0
    agree = 0; total = 0
    for i in range(n):
        for j in range(i+1, n):
            same_t = labels_true[i] == labels_true[j]
            same_p = labels_pred[i] == labels_pred[j]
            if same_t == same_p: agree += 1
            total += 1
    return agree / total


def pair_confusion_matrix(labels_true, labels_pred):
    """2x2 pair-counting confusion matrix."""
    labels_true = _np.asarray(labels_true); labels_pred = _np.asarray(labels_pred)
    n = len(labels_true)
    tp = tn = fp = fn = 0
    for i in range(n):
        for j in range(i+1, n):
            same_t = labels_true[i] == labels_true[j]
            same_p = labels_pred[i] == labels_pred[j]
            if same_t and same_p:    tp += 1
            elif same_t and not same_p: fn += 1
            elif not same_t and same_p: fp += 1
            else:                    tn += 1
    return _np.array([[tn, fp], [fn, tp]])


def contingency_matrix(labels_true, labels_pred, *, eps=None, sparse=False,
                        dtype=_np.int64):
    return _contingency(labels_true, labels_pred, dtype=dtype)


