def entropy(labels):
    """Shannon entropy of a label vector."""
    labels = _np.asarray(labels)
    if len(labels) == 0: return 0.0
    _, counts = _np.unique(labels, return_counts=True)
    p = counts / len(labels)
    return -_np.sum(p * _np.log(p + 1e-30))


def _contingency(labels_true, labels_pred, *, dtype=_np.int64):
    labels_true = _np.asarray(labels_true); labels_pred = _np.asarray(labels_pred)
    classes_true = _np.unique(labels_true)
    classes_pred = _np.unique(labels_pred)
    table = _np.zeros((len(classes_true), len(classes_pred)), dtype=dtype)
    for i, ct in enumerate(classes_true):
        for j, cp in enumerate(classes_pred):
            table[i, j] = ((labels_true == ct) & (labels_pred == cp)).sum()
    return table


def _conditional_entropy(labels_true, labels_pred):
    n = len(labels_true)
    cont = _contingency(labels_true, labels_pred)
    h = 0.0
    for k in range(cont.shape[1]):
        col = cont[:, k]
        n_k = col.sum()
        if n_k == 0: continue
        p_k = n_k / n
        col_p = col / n_k
        col_h = -_np.sum(col_p[col_p > 0] * _np.log(col_p[col_p > 0]))
        h += p_k * col_h
    return h
